#!/bin/sh
performance_menu(){ while :; do c=$(ui_menu Performance 'Safe user-space tuning for iSH-AOK.' profile 'Apply profile' build 'Parallel build settings' cargo 'Cargo configuration' shell 'Shell startup tuning' logs 'Logging retention' cache 'Clean caches' limits 'Edit resource limits' benchmark 'Run lightweight benchmark' report 'Capability report' advanced 'Advanced profiles, audits and benchmarks') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in profile) performance_profile;; build) n=$(ui_input Build 'Parallel jobs:' 2) || continue; replace_block "$CURRENT_HOME/.profile" build "export MAKEFLAGS=-j$n\nexport CMAKE_BUILD_PARALLEL_LEVEL=$n\nexport CARGO_BUILD_JOBS=$n";; cargo) mkdir -p "$CURRENT_HOME/.cargo"; ensure_template cargo "$CURRENT_HOME/.cargo/config.toml";; shell) replace_block "$CURRENT_HOME/.profile" shellperf 'export HISTFILESIZE=2000\nexport HISTSIZE=1000\nexport LESSHISTFILE=-';; logs) [ -e /etc/logrotate.conf ] && edit_file /etc/logrotate.conf || ui_msg Logs 'logrotate.conf is not installed.';; cache) package_clean; rm -rf "$CURRENT_HOME/.cache"/* 2>/dev/null || true;; limits) edit_file /etc/security/limits.conf;; benchmark) run_capture Benchmark sh -c 'time (i=0; while [ $i -lt 50000 ]; do i=$((i+1)); done)' ;; report) capability_report;; advanced) performance_advanced_menu;; esac; done; }
performance_profile(){ p=$(ui_menu Profile 'Select a safe profile.' low 'Low memory' balanced Balanced max 'Maximum user-space performance') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $p in low) n=1; hist=500;; balanced) n=2; hist=2000;; max) n=$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo 4); hist=5000;; esac; replace_block "$CURRENT_HOME/.profile" performance "export MAKEFLAGS=-j$n\nexport CMAKE_BUILD_PARALLEL_LEVEL=$n\nexport CARGO_BUILD_JOBS=$n\nexport HISTSIZE=$hist\nexport HISTFILESIZE=$hist"; ui_msg Profile "Applied $p profile."; }
capability_report(){ { uname -a; echo; echo 'aokfs:'; grep aokfs /proc/mounts 2>/dev/null || true; echo; echo 'sysctl writable tests:'; for k in kernel.pid_max vm.swappiness fs.file-max; do [ -w "/proc/sys/$(echo "$k"|tr . /)" ] && echo "$k writable" || echo "$k unavailable/read-only"; done; echo; cat /proc/self/limits 2>/dev/null; } >"$REPORT_DIR/capabilities.txt"; ui_text Capabilities "$(cat "$REPORT_DIR/capabilities.txt")"; }
